// The tokens and base rules of appkit-ui first: the look every app of appkit shares. The palette of this app sits
// between them: the colours of its icon (generated by palettes.mjs, never edited here).
import 'appkit-ui/tokens.css';
import './palette.css';
import 'appkit-ui/base.css';
import { takePairingCode } from 'appkit-ui/pair';
import { mount } from 'svelte';
import App from './App.svelte';
import { App as AppState } from './lib/app.svelte';
import { HubSource } from './lib/source';

const target = document.getElementById('app');
if (target === null) throw new Error('#app is missing');

// The code leaves the address bar before anything else happens.
const code = takePairingCode(window.location, window.history);

const fetchFn: typeof fetch = (input, init) => window.fetch(input, init);
const state = new AppState({
  hub: new HubSource(fetchFn),
  session: window.sessionStorage,
  sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
});
mount(App, { target, props: { app: state, code, languages: navigator.languages } });

// A link of `testing-hub open` pasted into a tab that is already open changes only the fragment: no reload. The
// page starts again with the new code; what ran before is stopped first.
window.addEventListener('hashchange', () => {
  const later = takePairingCode(window.location, window.history);
  if (later) {
    state.stop();
    void state.start(later);
  }
});
